package cn.balltv.portal;

import android.app.*;import android.graphics.*;import android.graphics.drawable.*;import android.content.*;import android.content.res.*;import android.net.Uri;import android.os.Build;import android.view.*;import android.widget.*;

final class Ui {
 static boolean LEAN=Build.VERSION.SDK_INT<=23;static boolean LIGHT;static int BG,CARD,GREEN,MUTED,TEXT,FOCUS,BORDER,LIVE;
 static boolean wantsLight(Context c){String mode=c.getSharedPreferences("appearance",0).getString("mode","auto");return ThemePolicy.light(mode,java.util.Calendar.getInstance().get(java.util.Calendar.HOUR_OF_DAY));}
 static void palette(boolean light){LIGHT=light;BG=light?0xfff2f4f8:0xff0a0e17;CARD=light?0xfffcfdff:0xff171e2b;GREEN=light?0xff1968d8:0xff88b7ff;MUTED=light?0xff647186:0xff9daac0;TEXT=light?0xff182437:0xfff4f7ff;FOCUS=light?0xffe4eeff:0xff243958;BORDER=light?0xffe0e5ed:0xff273144;LIVE=light?0xff178568:0xff62ddb8;}
 static{palette(false);}static boolean wantsLean(Context c){String mode=c.getSharedPreferences("performance",0).getString("mode","auto");android.app.ActivityManager manager=(android.app.ActivityManager)c.getSystemService(Context.ACTIVITY_SERVICE);return mode.equals("lean")||mode.equals("auto")&&(Build.VERSION.SDK_INT<=23||manager!=null&&manager.isLowRamDevice());}static int cardLimit(){return LEAN?16:32;}static void install(Context c){palette(wantsLight(c));LEAN=wantsLean(c);}
 static int dp(Context c,int n){return Math.round(n*c.getResources().getDisplayMetrics().density);}static float units(float n){return n*Resources.getSystem().getDisplayMetrics().density;}
 static TextView text(Context c,String s,int size,int color){TextView t=new TextView(c);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));t.setIncludeFontPadding(false);return t;}
 static void medium(TextView t){t.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));}
 static LinearLayout column(Context c){LinearLayout l=new LinearLayout(c);l.setOrientation(LinearLayout.VERTICAL);return l;}
 static Drawable surface(int color,float radius,int stroke,float line){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(units(radius));if(line>0)d.setStroke(Math.max(1,Math.round(units(line))),stroke);return d;}
 static Drawable shape(int color,int stroke){return surface(color,16,stroke==color?BORDER:stroke,stroke==color?.65f:1.6f);}
 static Drawable cardState(){StateListDrawable d=new StateListDrawable();d.addState(new int[]{android.R.attr.state_focused},surface(FOCUS,18,GREEN,2));d.addState(new int[]{android.R.attr.state_pressed},surface(FOCUS,18,GREEN,1));d.addState(new int[]{},surface(CARD,18,BORDER,.65f));return d;}
 static Button button(Context c,String s,View.OnClickListener listener){Button b=new Button(c);b.setId(View.generateViewId());b.setFocusable(true);b.setText(s);b.setTextSize(15);b.setAllCaps(false);b.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));b.setIncludeFontPadding(false);b.setGravity(Gravity.CENTER);b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(dp(c,40));b.setMinimumHeight(dp(c,40));b.setPadding(dp(c,14),dp(c,8),dp(c,14),dp(c,8));
  StateListDrawable d=new StateListDrawable();d.addState(new int[]{android.R.attr.state_focused},surface(FOCUS,13,GREEN,1.6f));d.addState(new int[]{android.R.attr.state_pressed},surface(FOCUS,13,GREEN,1));d.addState(new int[]{android.R.attr.state_activated},surface(LIGHT?0xffdeebff:0xff263c5d,13,Color.TRANSPARENT,0));d.addState(new int[]{},surface(LIGHT?0xffe9edf3:0xff1b2433,13,Color.TRANSPARENT,0));b.setBackground(d);if(LEAN&&Build.VERSION.SDK_INT>=21){b.setStateListAnimator(null);b.setElevation(0);}
  b.setTextColor(new ColorStateList(new int[][]{new int[]{-android.R.attr.state_enabled},new int[]{android.R.attr.state_activated},new int[]{}},new int[]{MUTED,GREEN,TEXT}));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,-2);lp.setMargins(dp(c,3),dp(c,3),dp(c,3),dp(c,3));b.setLayoutParams(lp);b.setOnClickListener(listener);return b;
 }
 static void focusSurface(View v,boolean focus){if(LEAN){v.animate().cancel();v.setScaleX(1f);v.setScaleY(1f);if(Build.VERSION.SDK_INT>=21)v.setElevation(0);return;}v.animate().scaleX(focus?1.015f:1f).scaleY(focus?1.015f:1f).setDuration(100).start();}
 static boolean webUrl(String s){try{Uri u=Uri.parse(s);return("https".equalsIgnoreCase(u.getScheme())||"http".equalsIgnoreCase(u.getScheme()))&&u.getHost()!=null&&u.getUserInfo()==null;}catch(Exception e){return false;}}
 static void external(Activity a,String url,boolean video){try{Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse(url));if(video)i.setDataAndType(Uri.parse(url),"video/*");a.startActivity(i);}catch(Exception e){Toast.makeText(a,"没有可用的外部"+(video?"播放器":"浏览器"),Toast.LENGTH_LONG).show();}}
 interface Choice{void choose(int index);}
 static Dialog dialog(Activity a,String title,View content){Dialog d=new Dialog(a);d.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout shell=column(a);shell.setPadding(dp(a,26),dp(a,24),dp(a,26),dp(a,18));shell.setBackground(surface(CARD,24,BORDER,.7f));LinearLayout brand=new LinearLayout(a);brand.setGravity(Gravity.CENTER_VERTICAL);ImageView logo=new ImageView(a);logo.setImageDrawable(new BrandMark());brand.addView(logo,new LinearLayout.LayoutParams(dp(a,26),dp(a,26)));TextView eyebrow=text(a,"  球场 TV",12,MUTED);brand.addView(eyebrow);shell.addView(brand);TextView heading=text(a,title,25,TEXT);medium(heading);heading.setPadding(0,dp(a,14),0,dp(a,20));shell.addView(heading);
  ScrollView scroll=new ScrollView(a){protected void onMeasure(int width,int height){super.onMeasure(width,View.MeasureSpec.makeMeasureSpec(Math.min(View.MeasureSpec.getSize(height)==0?Integer.MAX_VALUE:View.MeasureSpec.getSize(height),(int)(a.getResources().getDisplayMetrics().heightPixels*.55f)),View.MeasureSpec.AT_MOST));}};scroll.setFocusable(true);scroll.setDescendantFocusability(android.view.ViewGroup.FOCUS_AFTER_DESCENDANTS);scroll.setFillViewport(false);scroll.addView(content);shell.addView(scroll,new LinearLayout.LayoutParams(-1,-2));Button close=button(a,"返回",v->d.dismiss());shell.addView(close);d.setContentView(shell);Window w=d.getWindow();w.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams attrs=w.getAttributes();attrs.dimAmount=.5f;w.setAttributes(attrs);w.setWindowAnimations(LEAN?0:R.style.PanelMotion);w.getDecorView().setSystemUiVisibility(5894);d.show();w.setLayout(Math.min(dp(a,650),a.getResources().getDisplayMetrics().widthPixels-dp(a,72)),-2);Runnable initialFocus=()->{if(!scroll.hasWindowFocus())return;java.util.ArrayList<View> targets=new java.util.ArrayList<View>();scroll.addFocusables(targets,View.FOCUS_FORWARD);for(View target:targets)if(target instanceof Button||target instanceof EditText){target.requestFocus();return;}scroll.requestFocus();};scroll.getViewTreeObserver().addOnWindowFocusChangeListener(new android.view.ViewTreeObserver.OnWindowFocusChangeListener(){boolean assigned;public void onWindowFocusChanged(boolean focused){if(focused&&!assigned){assigned=true;initialFocus.run();}}});scroll.post(initialFocus);return d;
 }
 static void options(Activity a,String title,String[] labels,Choice callback){LinearLayout content=column(a);Dialog d=dialog(a,title,content);for(int i=0;i<labels.length;i++){final int index=i;Button item=button(a,labels[i]+"   ›",v->{d.dismiss();callback.choose(index);});item.setTextSize(16);item.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(a,50));p.bottomMargin=dp(a,6);content.addView(item,p);}}
 static void selectedOptions(Activity a,String title,String[] labels,int selected,Choice callback){LinearLayout content=column(a);Dialog d=dialog(a,title,content);final Button[] current=new Button[1];for(int i=0;i<labels.length;i++){final int index=i;boolean chosen=i==selected;Button item=button(a,(chosen?"✓ ":"   ")+labels[i],v->{d.dismiss();callback.choose(index);});item.setTextSize(16);item.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);item.setActivated(chosen);item.setSelected(chosen);item.setContentDescription(labels[i]+(chosen?"，当前已选":""));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(a,50));p.bottomMargin=dp(a,6);content.addView(item,p);if(chosen)current[0]=item;}Runnable focus=()->{if(d.isShowing()&&content.hasWindowFocus()&&current[0]!=null)current[0].requestFocus();};content.getViewTreeObserver().addOnWindowFocusChangeListener(new android.view.ViewTreeObserver.OnWindowFocusChangeListener(){boolean assigned;public void onWindowFocusChanged(boolean has){if(has&&!assigned){assigned=true;focus.run();}}});content.post(focus);}
 static void message(Activity a,String title,String body){TextView text=text(a,body,16,MUTED);text.setLineSpacing(dp(a,6),1);text.setPadding(0,0,0,dp(a,16));dialog(a,title,text);}
}
